{
    static InvCfg cfg;
    char mode[16];
    unsigned ls, lw, ms, mw, hs, hw, d;

    if (scanf("%15s", mode) != 1) return 1;
    if (scanf(" L %u %u M %u %u H %u %u %u", &ls, &lw, &ms, &mw, &hs, &hw, &d) != 7) return 1;
